"""Build the distributable single-file Bash installer from the Python source."""
from pathlib import Path

BASE = Path(__file__).resolve().parent
HEADER = r'''#!/usr/bin/env bash
# sbv6 standalone installer; generated by build_installer.py. GPL-3.0.
set -euo pipefail

bootstrap_dependencies() {
  local needs=0 command_name
  if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
    case "${1:-}" in -h|--help|-l|-d) ;; *) echo '请使用 sudo bash sbv6.sh 或以 root 运行。' >&2; return 1 ;; esac
  fi
  # Read-only help and offline uninstall do not install unrelated packages.
  case "${1:-}" in
    -h|--help|-u|-l|-d|-f|-s) command -v python3 >/dev/null 2>&1 || needs=1 ;;
    *) for command_name in python3 curl openssl ip ss; do
         command -v "$command_name" >/dev/null 2>&1 || needs=1
       done ;;
  esac
  if [[ "$needs" == 1 ]]; then
    [[ ${EUID:-$(id -u)} -eq 0 ]] || { echo '安装 Python 需要 root 权限。' >&2; return 1; }
    echo '正在安装 sbv6 运行依赖……'
    if command -v apt-get >/dev/null 2>&1; then
      apt-get update
      DEBIAN_FRONTEND=noninteractive apt-get install -y python3 curl openssl iproute2 ca-certificates
    elif command -v apk >/dev/null 2>&1; then
      apk add --no-cache python3 curl openssl iproute2 ca-certificates
    elif command -v dnf >/dev/null 2>&1; then
      dnf install -y python3 curl openssl iproute ca-certificates
    elif command -v yum >/dev/null 2>&1; then
      yum install -y python3 curl openssl iproute ca-certificates
    elif command -v zypper >/dev/null 2>&1; then
      zypper --non-interactive install python3 curl openssl iproute2 ca-certificates
    else
      echo '请先安装 Python 3.9+、curl、openssl、iproute2、CA 证书。' >&2; return 1
    fi
  fi
  python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 9) else "需要 Python 3.9 或更新版本")'
}

bootstrap_dependencies "$@"
SBV6_INSTALL_TMP=$(mktemp -d "${TMPDIR:-/tmp}/sbv6-installer.XXXXXXXX")
trap 'rm -rf -- "$SBV6_INSTALL_TMP"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
cat > "$SBV6_INSTALL_TMP/sbv6.py" <<'SBV6_EMBEDDED_PYTHON_END'
'''
FOOTER = '''SBV6_EMBEDDED_PYTHON_END
python3 "$SBV6_INSTALL_TMP/sbv6.py" "$@"
'''

def build():
    source = (BASE / 'sbv6.py').read_text(encoding='utf-8')
    if '\nSBV6_EMBEDDED_PYTHON_END\n' in source:
        raise ValueError('Payload contains heredoc delimiter')
    target = BASE / 'sbv6.sh'
    target.write_text(HEADER + source.rstrip() + '\n' + FOOTER, encoding='utf-8', newline='\n')
    return target

if __name__ == '__main__': print(build())
